        position = sandbox.get_boat_position()
        hull_y = float(position[1]) if position else 2.5
        return hull_y + 0.2, hull_y  # Deck top (0.2m above hull center), hull Y position

    def _check_mass(sandbox):
        total_mass = sandbox.get_structure_mass()
        if total_mass > sandbox.MAX_STRUCTURE_MASS:
            raise ValueError(
                f"Structure mass {total_mass:.2f} kg exceeds limit "
                f"{sandbox.MAX_STRUCTURE_MASS:.2f} kg"
            )

    # Define key positions based on hull state
    deck_top, hull_y = _hull_deck_top(sandbox)
    build_y_min = 2.0
    max_mass = float(sandbox.MAX_STRUCTURE_MASS)
    reference_mass = 59.61
    density_scale = (
        1.0
        if max_mass >= reference_mass - 0.05
        else min(1.0, max(0.35, (max_mass - 0.25) / reference_mass))
    )

    def density(value):
        return float(value) * density_scale

    # Add heavy ballast to lower center of mass
    for x in (14.25, 15.75):
        ballast_beam = sandbox.add_beam(
            x, hull_y - 0.2, 0.5, 0.17, density=density(300.0)
        )
        sandbox.set_material_properties(ballast_beam, restitution=0.01)
        sandbox.add_joint(ballast_beam, None, (x, hull_y - 0.2), type="rigid")

    # Add vertical containment beams on both sides
    for x in (13.5, 16.5):
        vertical_beam = sandbox.add_beam(
            x, deck_top - 0.2, 0.2, 1.5, density=density(200.0)
        )
        sandbox.set_material_properties(vertical_beam, restitution=0.01)
        sandbox.add_joint(vertical_beam, None, (x, deck_top - 0.2), type="rigid")

    # Add horizontal barriers to block loss plane and prevent lateral movement
    for y in (2.1, 2.3):
        horizontal_beam = sandbox.add_beam(
            15.0, y, 3.0, 0.08, density=density(150.0)
        )
        sandbox.set_material_properties(horizontal_beam, restitution=0.01)
        sandbox.add_joint(horizontal_beam, None, (15.0, y), type="rigid")

    # Add lower deck stops for containment
    for x in (14.5, 15.5):
        stop_beam = sandbox.add_beam(
            x, deck_top - 0.3, 0.26, 0.2, density=density(250.0)
        )
        sandbox.set_material_properties(stop_beam, restitution=0.01)
        sandbox.add_joint(stop_beam, None, (x, deck_top - 0.3), type="rigid")

    _check_mass(sandbox)
    return sandbox.get_boat_body()

